def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        seen = set()
        minimized = []
        for cls in classes:
            if cls not in seen:
                if not any(issubclass(cls, c) for c in seen):
                    minimized.append(cls)
                    seen.add(cls)
                else:
                    # Remove classes that are superclasses of the current class
