def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}

    try:
        version_data = inventory.get(version)
        if not version_data:
            raise ValueError(f"Version {version} not found in inventory.")

        for logical_path, content_files in version_data.items():
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
            logical_path_map[logical_path].update(content_files)

        # Include potential duplicates from later versions
        later_versions = [v for v in inventory if v > version]
        for v in later_versions:
            later_version_data = inventory.get(v, {})
            for logical_path, content_files in later_version_data.items():
                if logical_path in logical_path_map:
                    logical_path_map[logical_path].update(content_files)

    except Exception as e:
        raise ValueError(f"Error processing inventory for version {version}: {str(e)}")

    return logical_path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    from collections import defaultdict

    logical_path_map = defaultdict(set)

    try:
        # Ensure version is in the inventory
        if version not in inventory:
            raise ValueError(f"Version {version} not found in inventory.")

        # Iterate over the inventory for the specified version
        for logical_path, file_info in inventory[version].items():
            # Add the file path to the set of content files for the logical path
            logical_path_map[logical_path].add(file_info['file_path'])

            # Check for duplicates in later versions
            for later_version in sorted(v for v in inventory if v > version):
                if logical_path in inventory[later_version]:
                    logical_path_map[logical_path].add(inventory[later_version][logical_path]['file_path'])

    except Exception as e:
        raise RuntimeError(f"An error occurred while generating the logical path map: {e}")

    return dict(logical_path_map)

