def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    xml_filename : str
        XML filenames
    files : list
        list of files in the folder or zipfile

    Returns
    -------
    dict
        key: name of the XML files
        value: Package
    """
    from os.path import basename

    grouped_files = {}
    try:
        xml_basenames = {basename(xml): xml for xml in xmls}
        for file in files:
            file_base = basename(file)
            for xml_base, xml_path in xml_basenames.items():
                if file_base.startswith(xml_base.split('.')[0]):
                    if xml_path not in grouped_files:
                        grouped_files[xml_path] = []
                    grouped_files[xml_path].append(file)
    except Exception as e:
        print(f"An error occurred: {e}")
    return grouped_files

