def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from copy import deepcopy

    def apply_absorption(expr1, expr2):
        if expr1 == expr2[0] and (expr2[1] == '|' or expr2[1] == '&'):
            if expr1 == expr2[2] or expr2[2] == ('~', expr1):
                return expr1
        return None

    def apply_negative_absorption(expr1, expr2):
        if expr2[1] == '|' and expr2[0] == ('~', expr1):
            return ('&', expr1, expr2[2])
        if expr2[1] == '&' and expr2[2] == ('~', expr1):
            return ('|', expr1, expr2[0])
        return None

    new_args = deepcopy(args)
    i = 0
    while i < len(new_args):
        absorbed = False
        for j in range(len(new_args)):
            if i != j:
                if isinstance(new_args[i], tuple) and isinstance(new_args[j], tuple):
                    result = apply_absorption(new_args[i][0], new_args[j])
                    if result:
                        new_args[i] = result
                        del new_args[j]
                        absorbed = True
                        break
                    result = apply_negative_absorption(new_args[i][0], new_args[j])
                    if result:
                        new_args[i] = result
                        del new_args[j]
                        absorbed = True
                        break
        if not absorbed:
            i += 1

    return new_args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if op == '&':
                if isinstance(right, tuple) and len(right) == 3:
                    right_op, right_left, right_right = right
                    if right_op == '|' and left == right_left:
                        result.append(left)  # A & (A | B) = A
                    elif right_op == '&' and left == ('~', right_left):
                        result.append(('&', left, right_right))  # A & (~A & B) = A & B
                    else:
                        result.append(expr)
                else:
                    result.append(expr)
            elif op == '|':
                if isinstance(right, tuple) and len(right) == 3:
                    right_op, right_left, right_right = right
                    if right_op == '&' and left == right_left:
                        result.append(left)  # A | (A & B) = A
                    elif right_op == '|' and left == ('~', right_left):
                        result.append(('|', left, right_right))  # A | (~A | B) = A | B
                    else:
                        result.append(expr)
                else:
                    result.append(expr)
            else:
                result.append(expr)
        else:
            result.append(expr)
    return result

