def _fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    if not dt.tzinfo:
        raise ValueError("The provided datetime object must be timezone-aware.")

    # Convert the datetime to UTC first, if it's not already
    if dt.tzinfo != self.utc:
        dt = dt.astimezone(self.utc)

    # Localize the datetime to the new timezone
    localized_dt = self.localize(dt.replace(tzinfo=None))

    # Check if the datetime is in a fold state
    if self._isfold(localized_dt):
        # Determine if it's the first occurrence or the second occurrence
        if dt.utcoffset() == self.utcoffset(localized_dt.replace(fold=0)):
            return localized_dt.replace(fold=0)
        else:
            return localized_dt.replace(fold=1)

    return localized_dt

