            return False

        for item, digest in inventory.items():
            if item not in root_inventory or root_inventory[item] != digest:
                content_digests.add(digest)

    for version in version_dirs:
        for item, digest in inventory.items():
            if digest not in content_digests:
                print(f"Digest for item {item} in version {version} is not in the expected content digests.")
                return False

    return True

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, list) or not all(isinstance(d, str) for d in version_dirs):
        raise ValueError("version_dirs must be a list of strings.")

    root_inventory = {}
    content_digests = set()

    for version_dir in version_dirs:
        try:
            # Load the inventory for the current version
            with open(f"{version_dir}/inventory.json", 'r') as f:
                version_inventory = json.load(f)
        except FileNotFoundError:
            raise FileNotFoundError(f"Inventory file not found for version: {version_dir}")
        except json.JSONDecodeError:
            raise ValueError(f"Invalid JSON in inventory file for version: {version_dir}")

        # Check if the version inventory contains all keys present in the root inventory
        for key, value in root_inventory.items():
            if key not in version_inventory or version_inventory[key] != value:
                raise ValueError(f"Mismatch in inventory for version: {version_dir}, key: {key}")

        # Update the root inventory with the current version's inventory
        root_inventory.update(version_inventory)

        # Collect content digests for validation
        for item in version_inventory.values():
            if isinstance(item, dict) and 'content_digest' in item:
                content_digests.add(item['content_digest'])

    # Further validation can be added here using content_digests as needed
    return content_digests

