def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    merged_dict = {}

    for key_node, value_node in nodes:
        if key_node not in merged_dict:
            merged_dict[key_node] = value_node
        else:
            if isinstance(value_node, MappingNode) and isinstance(merged_dict[key_node], MappingNode):
                merged_value = merged_dict[key_node].value
                new_value = value_node.value
                key_to_index = {k.value: i for i, (k, _) in enumerate(merged_value)}

                for new_key, new_val in new_value:
                    if new_key.value in key_to_index:
                        merged_value[key_to_index[new_key.value]] = (new_key, new_val)
                    else:
                        merged_value.append((new_key, new_val))
            else:
                merged_dict[key_node] = value_node

    return list(merged_dict.items())

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from collections import defaultdict

    def merge_mapping_nodes(node1, node2):
        if not isinstance(node1, ruamel.yaml.nodes.MappingNode) or not isinstance(node2, ruamel.yaml.nodes.MappingNode):
            return node2
        merged_value = defaultdict(list)
        for key, value in node1.value:
            merged_value[key].append(value)
        for key, value in node2.value:
            merged_value[key].append(value)
        merged_pairs = []
        for key, values in merged_value.items():
            if all(isinstance(v, ruamel.yaml.nodes.MappingNode) for v in values):
                new_value = merge_mapping_nodes(values[0], values[1])
                for v in values[2:]:
                    new_value = merge_mapping_nodes(new_value, v)
                merged_pairs.append((key, new_value))
            elif all(isinstance(v, ruamel.yaml.nodes.SequenceNode) for v in values):
                new_value = sum((v.value for v in values), [])
                merged_pairs.append((key, ruamel.yaml.nodes.SequenceNode(tag=node1.tag, value=new_value)))
            else:
                merged_pairs.append((key, values[-1]))
        return ruamel.yaml.nodes.MappingNode(tag=node1.tag, value=merged_pairs)

    merged_dict = {}
    for key, value in nodes:
        if key in merged_dict:
            merged_dict[key] = merge_mapping_nodes(merged_dict[key], value)
        else:
            merged_dict[key] = value
    return list(merged_dict.items())

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    merged_dict = {}

    for key_node, value_node in nodes:
        key = key_node.value
        if key not in merged_dict:
            merged_dict[key] = (key_node, value_node)
        else:
            _, existing_value_node = merged_dict[key]
            if isinstance(value_node, MappingNode) and isinstance(existing_value_node, MappingNode):
                existing_value_node.value.extend(value_node.value)
            else:
                merged_dict[key] = (key_node, value_node)

    # Resolve duplicate keys in MappingNodes
    for key, (key_node, value_node) in merged_dict.items():
        if isinstance(value_node, MappingNode):
            seen_keys = set()
            unique_values = []
            for key_node_inner, value_node_inner in value_node.value:
                if key_node_inner.value not in seen_keys:
                    unique_values.append((key_node_inner, value_node_inner))
                    seen_keys.add(key_node_inner.value)
            value_node.value = unique_values

    return list(merged_dict.values())

def deep_merge_nodes(nodes):
    merged = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key not in merged:
            merged[key] = (key_node, value_node)
        else:
            existing_key_node, existing_value_node = merged[key]
            if isinstance(value_node, ruamel.yaml.nodes.MappingNode) and isinstance(existing_value_node, ruamel.yaml.nodes.MappingNode):
                existing_value_node.value.extend(value_node.value)
                # Remove duplicates by creating a dict from the list of tuples and converting back
                existing_value_node.value = list(dict(existing_value_node.value).items())
            else:
                merged[key] = (key_node, value_node)
    return list(merged.values())

