    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    try:
        import argparse
        import borgmatic.commands
    except ImportError as e:
        return f"# Error: {e}. Please ensure borgmatic and its dependencies are installed."

    def generate_completion(parser, command='', options=None):
        if options is None:
            options = set()

        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                for name, subparser in action.choices.items():
                    yield from generate_completion(subparser, f'{command} {name}' if command else name, options)
            elif action.option_strings:
                options.update(action.option_strings)

        if command:
            yield f'complete -W "{ " ".join(sorted(options)) }" {command}'

