def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess
    from pathlib import Path
    from typing import Optional, Union

    if filename is None:
        filename = Path(archive_path).stem

    tmp_path = Path(tmp_path)
    tmp_path.mkdir(parents=True, exist_ok=True)
    repo_path = tmp_path / filename
    repo_path.mkdir(parents=True, exist_ok=True)

    try:
        if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            subprocess.run(
                ['tar', '-xzf', archive_path, '-C', repo_path],
                check=True
            )
        elif archive_path.endswith('.zip'):
            subprocess.run(
                ['unzip', archive_path, '-d', repo_path],
                check=True
            )
        else:
            raise ValueError("Unsupported archive format")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Error extracting archive: {e}")

    return repo_path.resolve().as_uri()

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import shutil
    import tarfile
    import zipfile

    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"The archive file {archive_path} does not exist.")

    if isinstance(tmp_path, PosixPath):
        tmp_path = str(tmp_path)

    if not os.path.exists(tmp_path):
        os.makedirs(tmp_path)

    with os.scandir(tmp_path) as it:
        for entry in it:
            if entry.name.startswith(filename or "") and entry.is_dir():
                shutil.rmtree(entry.path)

    temp_dir = os.path.join(tmp_path, filename or os.path.basename(archive_path).rsplit('.', 1)[0])

    try:
        if tarfile.is_tarfile(archive_path):
            with tarfile.open(archive_path, 'r:*') as tar:
                tar.extractall(path=temp_dir)
        elif zipfile.is_zipfile(archive_path):
            with zipfile.ZipFile(archive_path, 'r') as zip_ref:
                zip_ref.extractall(temp_dir)
        else:
            raise ValueError("Unsupported archive format")
    except Exception as e:
        raise RuntimeError(f"Failed to extract the archive {archive_path}: {e}")

    return f"file://{temp_dir}"

