def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Get the list of all local ip addresses
        local_ips = {'127.0.0.1', '::1'}
        # Resolve the hostname to an ip address
        resolved_ips = socket.getaddrinfo(host, None)
        # Check if any of the resolved ips are in the local ip addresses
        return any(ip[4][0] in local_ips for ip in resolved_ips)
    except socket.gaierror:
        # If there's an error resolving the hostname, return False
        return False

