def oneline(script, separator=" && "):
    """
    converts a script to one line command.
    THis is useful to run a single ssh command and pass a one line script.

    :param script: The script to be converted to a one-liner.
    :param separator: The separator to use between lines in the one-liner, defaults to " && ".
    :return: A single line command string.
    """
    try:
        if not isinstance(script, str):
            raise ValueError("The script must be a string.")

        lines = script.strip().splitlines()
        return separator.join(line.strip() for line in lines if line.strip())
    except Exception as e:
        raise ValueError(f"An error occurred while converting the script to a one-liner: {e}")

