def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is None:
        if self.scale_value is None or self.scale_value == 0:
            raise ValueError("Graph has unknown or zero scale.")
        return self.scale_value
    else:
        if self.scale_value is None or self.scale_value == 0:
            raise ValueError("Cannot rescale a graph with unknown or zero scale.")
        try:
            other = float(other)
        except (ValueError, TypeError):
            raise TypeError("The scaling factor must be a numeric value.")

        scale_factor = other / self.scale_value
        for point in self.points:
            point[-1] *= scale_factor  # Rescale the last coordinate
            if hasattr(point, 'error'):
                point.error *= scale_factor  # Rescale the error if it exists
        self.scale_value = other

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is None:
        if self._scale is None or self._scale == 0:
            raise LenaValueError("Graph scale is unknown or zero, cannot rescale.")
        return self._scale
    else:
        try:
            new_scale = float(other)
        except (TypeError, ValueError):
            raise LenaValueError("Scale must be a numeric value.")

        if new_scale == 0:
            raise LenaValueError("Scale cannot be zero.")

        if self._scale is None or self._scale == 0:
            raise LenaValueError("Graph scale is unknown or zero, cannot rescale.")

        scale_factor = new_scale / self._scale
        if self.fields:
            last_field_index = -1  # Assume the last field is the one to rescale
            for i, field in enumerate(self.fields):
                if field.has_errors():
                    for error in field.errors:
                        error.value *= scale_factor
                if 'z' in field.name or 'y' in field.name or '1' in field.name:  # Assuming 'z', 'y', or '1' denote the last coordinate
                    last_field_index = i
            if last_field_index != -1:
                self.fields[last_field_index].values = [
                    value * scale_factor for value in self.fields[last_field_index].values
                ]
            self._scale = new_scale
        else:
            raise LenaValueError("Graph has no fields, cannot rescale.")

