    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import zope.interface

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append("Candidate does not claim to provide the interface.")

    for name in iface.names():
        if name not in candidate.__dict__ and not hasattr(candidate, name):
            errors.append(f"Candidate does not define required attribute or method '{name}'.")

    for name, iface_attribute in iface.getAttributes().items():
        if hasattr(candidate, name):
            attr_value = getattr(candidate, name)
            if not iface_attribute.validate(attr_value):
                errors.append(f"Attribute '{name}' does not conform to the interface specification.")
        else:
            errors.append(f"Required attribute '{name}' is missing from candidate.")

    for name, iface_method in iface.getMethods().items():
        if hasattr(candidate, name):
            candidate_method = getattr(candidate, name)
            if not callable(candidate_method):
                errors.append(f"Attribute '{name}' is not callable, expected a method.")
                continue
            try:
                zope.interface.adapter.verifyObjectMethod(iface, iface_method, candidate_method)
            except zope.interface.exceptions.Invalid as e:
                errors.append(f"Method '{name}' does not conform to the interface specification: {e}")
        else:
            errors.append(f"Required method '{name}' is missing from candidate.")

    if errors:
        if len(errors) == 1:
            raise zope.interface.exceptions.Invalid(errors[0])
        else:
            raise zope.interface.exceptions.Invalid("\n".join(errors))

    return True

