def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re

    tags = set()
    pattern = re.compile(r'`.*?`|(?P<tag>#\w+)')
    code_block = False
    replaced_text = []

    for match in pattern.finditer(text):
        content = match.group()
        if content.startswith('`'):
            code_block = not code_block
            replaced_text.append(content)
        elif not code_block and match.group('tag'):
            tag = match.group('tag')
            tags.add(tag)
            if replacer:
                replaced_text.append(replacer(tag))
            else:
                replaced_text.append(tag)
        else:
            replaced_text.append(content)
    if not code_block:
        replaced_text.append(text[pattern.end():])

    return tags, ''.join(replaced_text)

