def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    plugin_spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
    flat_dict = {}

    try:
        with open(plugin_spec_path, 'r') as file:
            plugin_spec = json.load(file)

        def flatten(d, parent_key=''):
            for k, v in d.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                if isinstance(v, dict):
                    flat_dict.update(flatten(v, new_key))
                else:
                    flat_dict[new_key] = v

        flatten(plugin_spec)
        return flat_dict

    except FileNotFoundError:
        raise FileNotFoundError(f"plugin_spec.json not found in the directory: {plugin_dir}")
    except json.JSONDecodeError:
        raise ValueError(f"Invalid JSON format in plugin_spec.json in the directory: {plugin_dir}")
    except Exception as e:
        raise Exception(f"An error occurred while processing plugin_spec.json in the directory: {plugin_dir}. Error: {str(e)}")

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def flatten_dict(d, parent_key='', sep='_'):
        """Helper function to flatten a nested dictionary."""
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    plugin_spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
    if not os.path.isfile(plugin_spec_path):
        raise FileNotFoundError(f"Plugin spec file not found at: {plugin_spec_path}")

    try:
        with open(plugin_spec_path, 'r', encoding='utf-8') as f:
            plugin_spec = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Error decoding JSON from plugin spec file: {e}")

    return flatten_dict(plugin_spec)

